            <div class="quote-layout">
                <section class="tool-panel">
                    <div class="quote-fields">
                        <label>报价单编号<input id="quoteNo" type="text" maxlength="60"></label><label>报价日期<input id="quoteDate" type="date"></label>
                        <label>报价方<input id="seller" type="text" maxlength="120" placeholder="公司或个人名称"></label><label>联系信息<input id="sellerContact" type="text" maxlength="200" placeholder="电话、邮箱或地址"></label>
                        <label>客户名称<input id="buyer" type="text" maxlength="120"></label><label>币种<select id="currency"><option value="CNY">人民币（¥）</option><option value="USD">美元（$）</option><option value="EUR">欧元（€）</option></select></label>
                    </div>
                    <div class="quote-items-head"><h3>报价项目</h3><button class="btn small" id="addItem" type="button">+ 添加项目</button></div>
                    <div class="quote-items" id="items"></div>
                    <div class="quote-options"><label>折扣（%）<input id="discount" type="number" min="0" max="100" step="0.01" value="0"></label><label>税率（%）<input id="taxRate" type="number" min="0" max="100" step="0.01" value="0"></label></div>
                    <label for="notes">备注（可选）</label><textarea id="notes" maxlength="1500" placeholder="例如：报价有效期、付款方式、交付周期等。"></textarea>
                    <div class="btn-row"><button class="btn success" id="print" type="button">打印 / 保存 PDF</button><button class="btn" id="save" type="button">保存草稿</button><button class="btn secondary" id="clear" type="button">清空</button></div>
                    <p class="quote-status" id="status" role="status" aria-live="polite">报价数据仅保存在当前浏览器。报价单不是正式发票，请确认金额、税率及适用规则。</p>
